<template>
 <view class="secondary-page"><canvas canvas-id="enrollment-poster" class="poster-canvas"/>
  <view class="enrollment-nav"><NativeStatusSpacer/><button class="nav-back" @tap="goBack">‹</button><text>{{tab==='invite'?(parent?'填写班级邀请码':'班级入学邀请码'):(parent?'申请记录':'入学申请审核')}}</text></view>
  <view v-if="tab==='requests'" class="requests-heading"><view class="organization-line"><text>{{organization?.name}}</text><button v-if="can(parent?'STUDENT_ENROLLMENT_REQUEST_CREATE':'STUDENT_ENROLLMENT_INVITE_CREATE')" :disabled="busy" @tap="tab='invite'">{{parent?'填写邀请码':'班级邀请码'}} ›</button></view><view class="segmented status-tabs"><button v-for="(label,i) in ['待审核','已通过','已拒绝']" :key="label" :class="{active:statusIndex===i}" :disabled="busy" @tap="switchStatus(i)">{{label}} ({{statusCounts[i]}})</button></view></view><view v-if="tab!=='requests'&&!compactInvitation" class="section">
   <text class="field-label">{{parent?'当前家庭':'管理组织'}}</text><view class="picker-field"><text>{{organization?.name||'请从我的组织重新进入组织'}}</text></view>
   <view class="segmented"><button :class="{active:tab==='requests'}" :disabled="busy" @tap="tab='requests';loadRequests()">{{parent?'申请记录':'入学审核'}}</button><button v-if="can(parent?'STUDENT_ENROLLMENT_REQUEST_CREATE':'STUDENT_ENROLLMENT_INVITE_CREATE')" :class="{active:tab==='invite'}" :disabled="busy" @tap="tab='invite'">{{parent?'填写邀请码':'班级邀请码'}}</button></view>
   <template v-if="tab==='requests'"><view class="segmented status-tabs"><button v-for="(label,i) in ['待审核','已通过','已拒绝']" :key="label" :class="{active:statusIndex===i}" :disabled="busy" @tap="switchStatus(i)">{{label}}<text v-if="statusCounts[i]" class="count-chip"> ({{statusCounts[i]}})</text></button></view></template>
   <template v-else-if="parent">
    <text class="field-label">成长小主人<text class="required">*</text></text><picker :range="children" range-key="studentName" :value="childIndex" :disabled="busy" @change="chooseChild"><view class="picker-field"><text>{{children[childIndex]?.studentName||'选择成长小主人'}}</text><text>⌄</text></view></picker>
    <text class="field-label">班级入学邀请码<text class="required">*</text></text><input v-model="code" placeholder="填写收到的班级邀请码" :disabled="busy" @input="invitation=null"/><button class="primary block-action" :disabled="busy||!code.trim()" @tap="resolve">核验邀请码</button>
   </template>
   <template v-else><text class="field-label">班级<text class="required">*</text></text><picker :range="scopedClasses" range-key="name" :value="classIndex" :disabled="busy" @change="chooseClass"><view class="picker-field"><text>{{scopedClasses[classIndex]?.name||'选择班级'}}</text><text>⌄</text></view></picker><button class="primary block-action" :disabled="busy||!scopedClasses[classIndex]" @tap="issue">生成入学邀请码</button></template>
  </view>
  <text v-if="error" class="error">{{error}}</text><view v-if="busy" class="empty">正在处理…</view>
  <template v-if="tab==='invite'">
   <view v-if="parent&&invitation" class="section"><view class="section-heading"><text class="section-title">入学信息</text><text class="badge">已核验</text></view><view class="detail-line"><text>学校 / 培训机构</text><text>{{invitation.institutionName}}</text></view><view class="detail-line"><text>班级</text><text>{{invitation.className}}</text></view><text class="meta">有效期至 {{enrollmentDate(invitation.expiresAt)}}</text><button class="primary block-action" :disabled="busy||!studentUserId||!organization" @tap="apply">提交入学申请</button></view>
   <view v-else-if="!parent&&invitation?.inviteCode" class="section invitation-card">
    <view class="invitation-class"><view class="person"><PrototypeIcon name="school" :size="38"/></view><view class="person-copy"><text class="name">{{invitation.className}}</text><text class="meta">{{invitation.institutionName}}</text></view></view>
    <view class="qr-content"><view class="qr-main"><InvitationQrCode :value="invitation.inviteCode" :size="200"/><view class="code-copy"><text class="code-label">入学邀请码</text><button class="copy-code" :disabled="busy" @tap="copyCode"><text class="invite-code">{{invitation.inviteCode}}</text><PrototypeIcon name="copy" tone="muted" :size="30"/></button></view></view><view class="expiry-line"><text class="meta">有效期至 {{enrollmentDate(invitation.expiresAt)}}</text><text class="badge" :class="{expired:invitationExpired}">{{invitationExpired?'已过期':'有效'}}</text></view></view><view class="invitation-warning"><PrototypeIcon name="alert" tone="amber" :size="30"/><view><text>该邀请码仅限本校本班使用</text><text>请勿分享给其他学校或机构</text></view></view>
    <view class="invitation-actions"><button class="secondary action-cell" :disabled="busy" @tap="issue"><view class="action-symbol"><PrototypeIcon name="refresh" tone="muted" :size="40"/></view><text class="action-label">刷新邀请码</text></button><button class="secondary action-cell" :disabled="busy||!invitation.id" @tap="startExpiryEdit"><view class="action-symbol"><PrototypeIcon name="clock" tone="muted" :size="40"/></view><text class="action-label">设置有效期</text></button><button class="secondary action-cell" :disabled="busy" @tap="openPoster"><view class="action-symbol"><PrototypeIcon name="image" tone="muted" :size="40"/></view><text class="action-label">生成海报</text></button></view>
    <view v-if="expiryEditing" class="reject-form"><text class="field-label">有效期（天）<text class="required">*</text></text><input v-model="expiryDays" class="expiry-input" type="number" placeholder="请输入有效天数（1-30）" maxlength="3" :disabled="busy"/><view class="action-grid"><button class="secondary" :disabled="busy" @tap="expiryEditing=false">取消</button><button class="primary" :disabled="busy" @tap="saveExpiry">确认保存</button></view></view>

   </view>
  </template>
  <template v-else>
   <view v-for="item in requests" :key="item.id" class="request-summary" @tap="openRequest(item)"><view class="person"><PrototypeIcon name="user" :size="36"/></view><view class="request-copy"><view class="summary-title"><text class="name">{{item.studentName}}</text><text class="badge" :class="item.status">{{statusName(item.status)}}</text></view><text class="summary-meta">申请班级：{{item.className}}</text><text class="summary-meta">申请时间：{{enrollmentDate(item.createdAt)}}</text><text class="summary-meta">申请人：{{item.applicantName||'—'}} {{maskedMobile(item.applicantMobile)}}</text></view><text class="request-arrow">›</text></view>
   <view v-if="selectedRequest" class="sheet-mask"><view class="request-sheet"><view class="sheet-title"><text>申请详情</text><button :disabled="busy" @tap="closeRequest">关闭</button></view><view v-for="item in [selectedRequest]" :key="item.id"><text class="name">{{item.studentName}}</text>
    <view class="detail-line"><text>申请组织</text><text>{{item.institutionName}}</text></view><view class="detail-line"><text>申请班级</text><text>{{item.className}}</text></view><view class="detail-line"><text>申请时间</text><text>{{enrollmentDate(item.createdAt)}}</text></view><view v-if="item.applicantName" class="detail-line"><text>申请人</text><text>{{item.applicantName}}{{maskedMobile(item.applicantMobile)?' '+maskedMobile(item.applicantMobile):''}}</text></view><view v-if="item.reviewedAt" class="detail-line"><text>审核时间</text><text>{{enrollmentDate(item.reviewedAt)}}</text></view><text v-if="item.reviewReason" class="review-reason">审核意见：{{item.reviewReason}}</text>
    <template v-if="!parent&&item.status==='PENDING'&&can('STUDENT_ENROLLMENT_REVIEW')">
     <view v-if="rejecting!==item.id" class="action-grid"><button class="secondary" :disabled="busy" @tap="rejecting=item.id;reason=''">拒绝申请</button><button class="primary" :disabled="busy" @tap="review(item,true)">通过申请</button></view>
     <view v-else class="reject-form"><text class="field-label">拒绝原因<text class="required">*</text></text><textarea v-model="reason" placeholder="填写原因，便于申请人修改" maxlength="200" :disabled="busy"/><text class="counter">{{reason.length}} / 200</text><view class="action-grid"><button class="secondary" :disabled="busy" @tap="rejecting=''">取消</button><button class="danger" :disabled="busy||!reason.trim()" @tap="review(item,false)">确认拒绝</button></view></view>
    </template>
   </view>
   </view></view><view v-if="!busy&&!requests.length&&!error" class="section empty"><PrototypeIcon name="book" tone="muted" :size="64"/><text>暂无入学申请</text></view>
  </template>
 </view>
</template>
<script setup lang="ts">
import {createInvitationPoster} from '@/models/invitation-poster';
import NativeStatusSpacer from "@/components/NativeStatusSpacer.vue";
import InvitationQrCode from '@/components/InvitationQrCode.vue';
import {computed,ref} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import PrototypeIcon from '@/components/PrototypeIcon.vue';import {request} from '@/api/http';import {getOrganizationSession} from '@/session/organization-session';import {getParentSession} from '@/session/parent-session';import {onboardingApi,type MyOrganization} from '@/api/organization-onboarding';import {listManagedClasses,type OrganizationClass} from '@/api/organization-classes';import {parentChildrenApi,type Child} from '@/api/parent-children';import {institutionEnrollmentApi,enrollmentDate,maskedMobile,type InstitutionInvitation,type EnrollmentRequest} from '@/api/institution-enrollment';
const parent=ref(false),organizations=ref<MyOrganization[]>([]),orgIndex=ref(0),classes=ref<OrganizationClass[]>([]),classIndex=ref(0),children=ref<Child[]>([]),childIndex=ref(0),studentUserId=ref(''),permissions=ref<string[]>([]),tab=ref('requests'),busy=ref(false),error=ref(''),code=ref(''),invitation=ref<InstitutionInvitation|null>(null),requests=ref<EnrollmentRequest[]>([]),statusIndex=ref(0),statusCounts=ref<number[]>([0,0,0]),rejecting=ref(''),reason=ref('');const statuses=['PENDING','APPROVED','REJECTED'];const organization=computed(()=>organizations.value[orgIndex.value]);const scopedClasses=computed(()=>classes.value.filter(c=>c.id===organization.value?.id||c.schoolOrganizationId===organization.value?.id||c.parentId===organization.value?.id));const can=(p:string)=>permissions.value.includes(p);const session=()=>parent.value?getParentSession():getOrganizationSession();let epoch=0,requestedClass='';const valid=(n:number,t:string)=>n===epoch&&session()?.accessToken===t;
onLoad(q=>{parent.value=q?.identity==='parent';requestedClass=q?.classId||'';if(q?.code){code.value=q.code;tab.value='invite';}});function hide(){clearRequest();requestToken='';stopClock();epoch++;busy.value=false;expiryEditing.value=false;expiryDays.value='';invitation.value=null;studentUserId.value='';requests.value=[];statusCounts.value=[0,0,0];permissions.value=[];organizations.value=[];classes.value=[];children.value=[];childIndex.value=0;rejecting.value='';error.value='';}onHide(hide);onUnload(hide);
async function run<T>(task:(token:string)=>Promise<T>,done:(result:T)=>void){const s=session();if(!s||busy.value)return false;const n=++epoch;busy.value=true;error.value='';try{const result=await task(s.accessToken);if(valid(n,s.accessToken)){done(result);return true;}}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'请求失败';}finally{if(valid(n,s.accessToken))busy.value=false;}return false;}
onShow(async()=>{startClock();permissions.value=[];organizations.value=[];classes.value=[];children.value=[];const s=session();if(!s){uni.reLaunch({url:'/pages/unified-login/unified-login'});return;}const loaded=await run(async token=>{const initEpoch=epoch;const [me,orgs]=await Promise.all([request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}}),onboardingApi.organizations(token)]);if(!valid(initEpoch,token))throw new Error('页面会话已改变');const childPage={items:[] as Child[]};if(parent.value&&me.permissionCodes.includes('STUDENT_READ')){const n=initEpoch;let page=1,total=1;while(childPage.items.length<total){const rows=await parentChildrenApi.list(token,page++);if(!valid(n,token))throw new Error('页面会话已改变');childPage.items.push(...rows.items);total=rows.total;if(!rows.items.length)break;}}if(!valid(initEpoch,token))throw new Error('页面会话已改变');const cls=!parent.value&&me.permissionCodes.includes('CLASS_READ')?await listManagedClasses(token):[];return {me,orgs,childPage,cls};},result=>{permissions.value=result.me.permissionCodes;const stored=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string};organizations.value=result.orgs.filter(o=>stored?.accessToken===s.accessToken&&o.id===stored.organizationId).filter(o=>parent.value?o.typeCode==='FAMILY'&&o.canEnterFamily:o.canEnterInstitution&&['SCHOOL','TRAINING_INSTITUTION','CLASS'].includes(o.typeCode));classes.value=result.cls;children.value=result.childPage?.items||[];if(!organizations.value.length)error.value='当前组织不可用，请从我的组织重新进入组织';orgIndex.value=0;classIndex.value=Math.max(0,scopedClasses.value.findIndex(c=>c.id===requestedClass));});if(!loaded||session()?.accessToken!==s.accessToken||error.value)return;if(parent.value&&children.value.length){const childLoaded=await loadChild();if(!childLoaded)return;}await loadRequests();});
async function loadChild(){studentUserId.value='';const child=children.value[childIndex.value];if(!child)return false;return run(token=>request<Child&{studentUserId?:string}>(`/students/${encodeURIComponent(child.id)}`,{header:{Authorization:`Bearer ${token}`}}),detail=>{studentUserId.value=detail.studentUserId||'';if(!studentUserId.value)error.value='学生详情尚未提供入学申请所需的学生用户标识，请联系学校。';});}
async function loadRequests(){clearRequest();requestToken='';requests.value=[];if(!organization.value||!can(parent.value?'STUDENT_ENROLLMENT_REQUEST_CREATE':'STUDENT_ENROLLMENT_REVIEW')){if(can(parent.value?'STUDENT_ENROLLMENT_REQUEST_CREATE':'STUDENT_ENROLLMENT_INVITE_CREATE'))tab.value='invite';return;}const scopeKey=parent.value?'familyOrganizationId':organization.value!.typeCode==='CLASS'?'classOrganizationId':'institutionOrganizationId';const scopeId=organization.value!.id;await run(async token=>{const base={[scopeKey]:scopeId};const [current,pending,approved,rejected]=await Promise.all([institutionEnrollmentApi.list(token,{...base,status:statuses[statusIndex.value]}),institutionEnrollmentApi.list(token,{...base,status:'PENDING'}),institutionEnrollmentApi.list(token,{...base,status:'APPROVED'}),institutionEnrollmentApi.list(token,{...base,status:'REJECTED'})]);return {current,counts:[pending.length,approved.length,rejected.length]};},result=>{requestToken=session()?.accessToken||'';statusCounts.value=result.counts;requests.value=Array.isArray(result.current)?result.current:[];});}function chooseClass(e:{detail:{value:string}}){if(busy.value)return;classIndex.value=Number(e.detail.value);invitation.value=null;}function chooseChild(e:{detail:{value:string}}){if(busy.value)return;childIndex.value=Number(e.detail.value);loadChild();}function switchStatus(index:number){if(busy.value)return;clearRequest();statusIndex.value=index;loadRequests();}
async function authorize(token:string,permission:string){const n=epoch;const me=await request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}});if(!valid(n,token))throw new Error('页面会话已改变');if(!me.permissionCodes.includes(permission))throw new Error('当前操作权限已失效');}async function issue(){const c=scopedClasses.value[classIndex.value];if(!c||!can('STUDENT_ENROLLMENT_INVITE_CREATE'))return;await run(async token=>{await authorize(token,'STUDENT_ENROLLMENT_INVITE_CREATE');return institutionEnrollmentApi.issue(token,c.id);},value=>{invitation.value=value;});}async function resolve(){invitation.value=null;await run(token=>institutionEnrollmentApi.resolve(token,code.value.trim()),value=>{invitation.value=value;});}async function apply(){if(!studentUserId.value||!organization.value||!invitation.value||!can('STUDENT_ENROLLMENT_REQUEST_CREATE'))return;const target={studentUserId:studentUserId.value,familyOrganizationId:organization.value.id,code:code.value.trim()};const applied=await run(async token=>{await authorize(token,'STUDENT_ENROLLMENT_REQUEST_CREATE');return institutionEnrollmentApi.apply(token,target.studentUserId,target.familyOrganizationId,target.code);},()=>{uni.showToast({title:'申请已提交',icon:'success'});tab.value='requests';invitation.value=null;});if(applied)await loadRequests();}async function review(item:EnrollmentRequest,approved:boolean){if(busy.value||!can('STUDENT_ENROLLMENT_REVIEW')||(!approved&&!reason.value.trim()))return;const reviewReason=reason.value.trim();busy.value=true;const before=epoch,token=session()?.accessToken;const confirm=await uni.showModal({title:approved?'确认通过入学申请':'确认拒绝入学申请',content:`${item.studentName} · ${item.className}`});if(!confirm.confirm||before!==epoch||token!==session()?.accessToken){if(before===epoch)busy.value=false;return;}busy.value=false;const reviewed=await run(async t=>{await authorize(t,'STUDENT_ENROLLMENT_REVIEW');return approved?institutionEnrollmentApi.approve(t,item.id):institutionEnrollmentApi.reject(t,item.id,reviewReason);},()=>{clearRequest();uni.showToast({title:approved?'入学申请已通过':'入学申请已拒绝',icon:'success'});});if(reviewed)await loadRequests();}function copyCode(){if(invitation.value?.inviteCode)uni.setClipboardData({data:invitation.value.inviteCode});}
async function openPoster(){const current=invitation.value;if(parent.value||busy.value||!current?.inviteCode||!can('STUDENT_ENROLLMENT_INVITE_CREATE'))return;await run(async token=>{await authorize(token,'STUDENT_ENROLLMENT_INVITE_CREATE');return createInvitationPoster(uni,'enrollment-poster',current);},path=>{uni.previewImage({urls:[path],current:path});});}
const compactInvitation=computed(()=>!parent.value&&tab.value==='invite'&&!!invitation.value?.inviteCode);
const clock=ref(Date.now());let expiryTimer:ReturnType<typeof setInterval>|undefined;
function stopClock(){if(expiryTimer!==undefined)clearInterval(expiryTimer);expiryTimer=undefined;}
function startClock(){stopClock();clock.value=Date.now();expiryTimer=setInterval(()=>{clock.value=Date.now();},1000);}
const invitationExpired=computed(()=>!invitation.value||!Number.isFinite(Date.parse(invitation.value.expiresAt))||Date.parse(invitation.value.expiresAt)<=clock.value);
const selectedRequest=ref<EnrollmentRequest|null>(null);let requestToken='';
function clearRequest(){selectedRequest.value=null;rejecting.value='';reason.value='';}
function closeRequest(){if(!busy.value)clearRequest();}
function openRequest(item:EnrollmentRequest){if(busy.value||!requestToken||requestToken!==session()?.accessToken)return;const current=requests.value.find(r=>r.id===item.id);if(!current)return;clearRequest();selectedRequest.value=current;}
function goBack(){if(selectedRequest.value){closeRequest();return;}uni.navigateBack();}
const expiryEditing=ref(false),expiryDays=ref('');
function startExpiryEdit(){const current=invitation.value;if(!current?.id||busy.value)return;expiryDays.value='';expiryEditing.value=true;}
async function saveExpiry(){const current=invitation.value;if(!current?.id||busy.value)return;const days=Number(expiryDays.value.trim());if(!Number.isInteger(days)||days<1||days>30){error.value='有效天数必须为1至30';return;}const before=epoch,token=session()?.accessToken;const updated=await run(token=>institutionEnrollmentApi.updateExpiry(token,current.id!,days),value=>{expiryEditing.value=false;if(invitation.value&&invitation.value.id===current.id)invitation.value={...invitation.value,expiresAt:value.expiresAt};uni.showToast({title:'有效期已更新',icon:'success'});});if(!updated&&epoch===before+1&&session()?.accessToken===token)uni.showToast({title:error.value||'有效期更新失败',icon:'none'});}function statusName(s:string){return ({PENDING:'待审核',APPROVED:'已通过',REJECTED:'已拒绝'} as Record<string,string>)[s]||s;}
</script>
<style scoped>
.action-symbol{display:flex;align-items:center;justify-content:center}.invitation-warning{display:flex!important;align-items:flex-start;gap:12rpx}.invitation-warning text{display:block;line-height:1.6}

.detail-line{align-items:flex-start}.detail-line>text:first-child{flex:0 0 130rpx;white-space:nowrap}.detail-line>text:last-child{flex:1;min-width:0;overflow-wrap:anywhere;text-align:right}.request-person .name,.request-person .meta{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.picker-field>text:first-child{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.picker-field>text:last-child{flex-shrink:0}
.invitation-card .name,.invitation-card .meta{display:block;overflow-wrap:anywhere;white-space:normal}.invitation-card .invite-code{font-size:24rpx;letter-spacing:0;line-height:1.6;overflow-wrap:anywhere;word-break:break-all;}
